import json
import re
import sys
from pathlib import Path
from datetime import datetime
from typing import Dict, List, Optional, Tuple, Union

def parse_mailbox_file(file_path: Path) -> Dict[str, List[Dict]]:
    """Parse a mailbox export file into a dict mapping PO numbers to list of messages."""
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # Split by message separator
    messages = content.split('=' * 72 + '\n')[1:]  # Skip header before first separator

    po_data = {}
    for msg in messages:
        if not msg.strip():
            continue

        # Extract PO number
        po_match = re.search(r'PO-40\d{3}', msg)
        if not po_match:
            continue
        po = po_match.group(0)

        # Store the raw message text
        if po not in po_data:
            po_data[po] = []
        po_data[po].append(msg)

    return po_data

def extract_invoice_amount(text: str) -> Optional[str]:
    """Extract invoice amount from invoice message text."""
    # Look for dollar amounts with various formats
    patterns = [
        r'Invoice total is (\$[\d,]+(?:\.\d{2})?)',
        r'Invoice total is ([\d,]+(?:\.\d{2})?) dollars',
        r'The vendor\'s bill comes to (\$[\d,]+(?:\.\d{2})?)',
        r'The vendor\'s bill comes to ([\d,]+(?:\.\d{2})?) dollars',
        r'bill total.*?(\$[\d,]+(?:\.\d{2})?)',
    ]

    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            amount = match.group(1)
            # Clean up: remove $ and commas, ensure decimal format
            amount = amount.replace('$', '').replace(',', '')
            # Check if it has cents, add if not
            if '.' not in amount:
                amount = amount + '.00'
            return amount
    return None

def extract_invoice_quantity(text: str) -> Optional[str]:
    """Extract quantity invoiced from invoice message text."""
    patterns = [
        r'charged us for (\d+) (?:units|pieces)',
        r'lists (\d+) (?:units|pieces) as the chargeable count',
        r'Bill lists (\d+) (?:units|pieces)',
    ]

    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            return match.group(1)
    return None

def extract_invoice_due_date(text: str) -> Optional[str]:
    """Extract payment due date from invoice message text."""
    # Look for various date formats
    patterns = [
        r'no later than (\w+ \d+(?:st|nd|rd|th)?,? \d{4})',
        r'Payment has to go out by (\w+ \d+(?:st|nd|rd|th)?,? \d{4})',
