import json
import os
import sys
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

def parse_file(file_path: Path, delimiter: str = '|') -> List[Dict[str, str]]:
    """Parse a data file, skipping comment lines starting with '#'."""
    data = []
    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    # Find the header line (first non-comment line)
    header = None
    for line in lines:
        if not line.startswith('#'):
            header = line.strip().split(delimiter)
            break

    if header is None:
        return data

    # Process remaining lines
    for line in lines:
        if line.startswith('#') or line.strip() == '':
            continue
        if line.strip().split(delimiter) == header:
            continue  # Skip the header line itself

        parts = line.strip().split(delimiter)
        # Pad with empty strings if needed
        if len(parts) < len(header):
            parts.extend([''] * (len(header) - len(parts)))
        elif len(parts) > len(header):
            parts = parts[:len(header)]

        record = {header[i]: parts[i] for i in range(len(header))}
        data.append(record)

    return data

def mmddyyyy_to_yyyymmdd(date_str: str) -> Optional[str]:
    """Convert MM/DD/YYYY to YYYY-MM-DD."""
    if not date_str or date_str.strip() == '':
        return None
    try:
        parts = date_str.strip().split('/')
        if len(parts) != 3:
            return None
        month, day, year = parts
        return f"{year}-{month.zfill(2)}-{day.zfill(2)}"
    except:
        return None

def load_all_data(directory: Path) -> Dict[str, List[Dict[str, str]]]:
    """Load all data files from the directory."""
    files = {
        'invoices': 'invoices.txt',
        'payments': 'payments.txt',
        'purchase_orders': 'purchase_orders.txt',
        'receipts': 'receipts.txt',
        'requisitions': 'requisitions.txt',
        'warehouse_scans': 'warehouse_scans.txt'
    }

    data = {}
    for key, filename in files.items():
        file_path = directory / filename
        if file_path.exists():
            data[key] = parse_file(file_path)
        else:
            data[key] = []

    return data

def get_fact_value(
    data: Dict[str, List[Dict[str, str]]],
    purchase_document_key: str,
    fact_name: str,
    rule_name: str
) -> Union[List[str], str]:
    """Get the value for a fact according to the decision rules."""

    # Helper to find records for a specific purchase document
    def find_records(dataset: str) -> List[Dict[str, str]]:
        return [r for r in data.get(dataset, []) 
                if r.get('PURCHASE_DOCUMENT_KEY') == purchase_document_key]

    # Helper to check for conflicts
    def check_conflict(values: List[str]) -> Union[List[str], str]:
        unique_values = {v for v in values if v != ''}
        if len(unique_values) == 0:
            return "ABSENT"
        elif len(unique_values) == 1:
            return [list(unique_values)[0], dataset]
        else:
            return "CONFLICT"

    # pa.three_way_match facts
    if rule_name == "pa.three_way_match":
        if fact_name == "invoice amount":
            records = find_records('invoices')
            if not records:
                return "ABSENT"
            values = [r.get('VENDOR_BILLED_TOTAL', '') for r in records]
            return check_conflict(values)

        elif fact_name == "order amount":
            records = find_records('purchase_orders')
            if not records:
                return "ABSENT"
            values = [r.get('ORDER_NET_VALUE', '') for r in records]
            return check_conflict(values)

        elif fact_name == "quantity received":
            records = find_records('receipts')
            if not records:
                return "ABSENT"
            values = [r.get('GR_ACCEPTED_UNITS', '') for r in records]
            return check_conflict(values)

        elif fact_name == "quantity invoiced":
            records = find_records('invoices')
            if not records:
                return "ABSENT"
            values = [r.get('BILLED_UNIT_COUNT', '') for r in records]
            return check_conflict(values)

    # pa.paid_in_window facts
    elif rule_name == "pa.paid_in_window":
        if fact_name == "goods received":
            # First try receipts
            records = find_records('receipts')
            if records:
                values = []
                for r in records:
                    date_str = r.get('GR_POSTING_DAY', '')
                    if date_str:
                        values.append(mmddyyyy_to_yyyymmdd(date_str))
                if values:
                    unique_values = set(values)
                    if len(unique_values) == 1:
                        return [list(unique_values)[0], 'receipts']
                    else:
                        return "CONFLICT"

            # Fallback to warehouse_scans
            records = find_records('warehouse_scans')
            if records:
                values = []
                for r in records:
                    date_str = r.get('INBOUND_DOOR_EVENT_DAY', '')
                    if date_str:
                        values.append(mmddyyyy_to_yyyymmdd(date_str))
                if values:
                    unique_values = set(values)
                    if len(unique_values) == 1:
                        return [list(unique_values)[0], 'warehouse_scans']
                    else:
                        return "CONFLICT"

            return "ABSENT"

        elif fact_name == "payment date":
            records = find_records('payments')
            if not records:
                return "ABSENT"
            values = []
            for r in records:
                date_str = r.get('DISBURSEMENT_CLEARED_DAY', '')
                if date_str:
                    values.append(mmddyyyy_to_yyyymmdd(date_str))
            if not values:
                return "ABSENT"
            unique_values = set(values)
            if len(unique_values) == 1:
                return [list(unique_values)[0], 'payments']
            else:
                return "CONFLICT"

        elif fact_name == "payment due":
            records = find_records('invoices')
            if not records:
                return "ABSENT"
            values = []
            for r in records:
                date_str = r.get('NET_DUE_DAY', '')
                if date_str:
                    values.append(mmddyyyy_to_yyyymmdd(date_str))
            if not values:
                return "ABSENT"
            unique_values = set(values)
            if len(unique_values) == 1:
                return [list(unique_values)[0], 'invoices']
            else:
                return "CONFLICT"

    return "ABSENT"

def main():
