    try:
        # Ensure it's a valid decimal string
        float(amount_str.strip())
        return amount_str.strip()
    except ValueError:
        return None

def parse_quantity(qty_str):
    """Parse quantity string."""
    if not qty_str or qty_str.strip() == "":
        return None
    try:
        # Could be integer or decimal
        return qty_str.strip()
    except ValueError:
        return None

def read_document(filepath, doc_name):
    """Read a document file and return dict keyed by purchase_document_key."""
    data = defaultdict(list)
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            lines = f.readlines()
    except FileNotFoundError:
        return data

    # Find header line (first non-comment line)
    header = None
    for line in lines:
        if line.startswith('#'):
            continue
        header = line.strip().split('|')
        break

    if not header:
        return data

    # Read data lines
    for line in lines:
        if line.startswith('#') or line.strip() == '':
            continue
        if line.strip() == '|'.join(header):
            continue  # Skip header line itself

        parts = line.strip().split('|')
        if len(parts) != len(header):
            continue

        record = dict(zip(header, parts))
        key = record.get('PURCHASE_DOCUMENT_KEY')
        if key:
            data[key].append(record)

    return data

def extract_fact(purchase_key, doc_data, field_name, parser, doc_name):
    """Extract a fact from document data for a specific purchase key."""
    if purchase_key not in doc_data:
        return "ABSENT", None

    records = doc_data[purchase_key]
    values = []

    for record in records:
        value = record.get(field_name)
        if value is not None and value.strip() != "":
            parsed = parser(value)
            if parsed is not None:
                values.append(parsed)

    if not values:
        return "ABSENT", None

    # Check for conflicts
    unique_values = set(values)
    if len(unique_values) > 1:
        return "CONFLICT", None

    return values[0], doc_name

def main(directory_path):
    # Read all documents
    invoices = read_document(os.path.join(directory_path, "invoices.txt"), "invoices")
    payments = read_document(os.path.join(directory_path, "payments.txt"), "payments")
    purchase_orders = read_document(os.path.join(directory_path, "purchase_orders.txt"), "purchase_orders")
    receipts = read_document(os.path.join(directory_path, "receipts.txt"), "receipts")
    requisitions = read_document(os.path.join(directory_path, "requisitions.txt"), "requisitions")
    warehouse_scans = read_document(os.path.join(directory_path, "warehouse_scans.txt"), "warehouse_scans")

    # Define all purchase keys from the pairs
    all_keys = [f"PO-403{i:02d}" for i in range(1, 17)]

    result = {}

    # Process three_way_match pairs
    for key in all_keys:
        pair_id = f"pa.three_way_match::{key}"
        facts = {}

        # invoice amount
        value, doc = extract_fact(key, invoices, "VENDOR_BILLED_TOTAL", parse_amount, "invoices")
        if value == "ABSENT":
            facts["invoice amount"] = "ABSENT"
        elif value == "CONFLICT":
            facts["invoice amount"] = "CONFLICT"
        else:
            facts["invoice amount"] = [value, doc]

        # order amount
        value, doc = extract_fact(key, purchase_orders, "ORDER_NET_VALUE", parse_amount, "purchase_orders")
        if value == "ABSENT":
            facts["order amount"] = "ABSENT"
        elif value == "CONFLICT":
            facts["order amount"] = "CONFLICT"
        else:
            facts["order amount"] = [value, doc]

        # quantity received
        value, doc = extract_fact(key, receipts, "GR_ACCEPTED_UNITS", parse_quantity, "receipts")
        if value == "ABSENT":
            facts["quantity received"] = "ABSENT"
        elif value == "CONFLICT":
            facts["quantity received"] = "CONFLICT"
        else:
            facts["quantity received"] = [value, doc]

        # quantity invoiced
