        if value == "ABSENT":
            facts["quantity invoiced"] = "ABSENT"
        elif value == "CONFLICT":
            facts["quantity invoiced"] = "CONFLICT"
        else:
            facts["quantity invoiced"] = [value, doc]

        result[pair_id] = facts

    # Process paid_in_window pairs
    for key in all_keys:
        pair_id = f"pa.paid_in_window::{key}"
        facts = {}

        # goods received - first try receipts, then warehouse_scans
        value1, doc1 = extract_fact(key, receipts, "GR_POSTING_DAY", parse_date, "receipts")
        if value1 not in ["ABSENT", "CONFLICT"]:
            facts["goods received"] = [value1, doc1]
        else:
            # Fallback to warehouse_scans
            value2, doc2 = extract_fact(key, warehouse_scans, "INBOUND_DOOR_EVENT_DAY", parse_date, "warehouse_scans")
            if value2 == "ABSENT":
                facts["goods received"] = "ABSENT"
            elif value2 == "CONFLICT":
                facts["goods received"] = "CONFLICT"
            else:
                facts["goods received"] = [value2, doc2]

        # payment date
        value, doc = extract_fact(key, payments, "DISBURSEMENT_CLEARED_DAY", parse_date, "payments")
        if value == "ABSENT":
            facts["payment date"] = "ABSENT"
        elif value == "CONFLICT":
            facts["payment date"] = "CONFLICT"
        else:
            facts["payment date"] = [value, doc]

        # payment due
        value, doc = extract_fact(key, invoices, "NET_DUE_DAY", parse_date, "invoices")
        if value == "ABSENT":
            facts["payment due"] = "ABSENT"
        elif value == "CONFLICT":
            facts["payment due"] = "CONFLICT"
        else:
