from datetime import datetime
from html.parser import HTMLParser

class SheetParser(HTMLParser):
    """Parse a single sheet (article) from the HTML files."""
    def __init__(self):
        super().__init__()
        self.in_sheet = False
        self.in_table = False
        self.in_th = False
        self.in_td = False
        self.current_th = ""
        self.current_td = ""
        self.data = {}
        self.procurement_ref = None

    def handle_starttag(self, tag, attrs):
        if tag == "article" and any(attr[0] == "class" and "sheet" in attr[1] for attr in attrs):
            self.in_sheet = True
        elif self.in_sheet and tag == "table" and any(attr[0] == "class" and "fields" in attr[1] for attr in attrs):
            self.in_table = True
        elif self.in_table and tag == "th":
            self.in_th = True
            self.current_th = ""
        elif self.in_table and tag == "td":
            self.in_td = True
            self.current_td = ""

    def handle_endtag(self, tag):
        if tag == "th" and self.in_th:
            self.in_th = False
        elif tag == "td" and self.in_td:
            self.in_td = False
            # Store the data
            if self.current_th and self.current_td:
                key = self.current_th.strip()
                value = self.current_td.strip()
                if key == "Procurement reference":
                    # Extract PO number from strong tag or plain text
                    match = re.search(r"PO-\d+", value)
                    if match:
                        self.procurement_ref = match.group(0)
                else:
                    self.data[key] = value
            self.current_th = ""
            self.current_td = ""
        elif tag == "table" and self.in_table:
            self.in_table = False
        elif tag == "article" and self.in_sheet:
            self.in_sheet = False

    def handle_data(self, data):
        if self.in_th:
            self.current_th += data
        elif self.in_td:
            self.current_td += data

def parse_html_file(filepath):
    """Parse an HTML file and return a dict mapping PO numbers to sheet data."""
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    # Split by article tags to get individual sheets
    articles = re.findall(r'<article[^>]*class="sheet"[^>]*>.*?</article>', content, re.DOTALL)
    result = {}

    for article in articles:
        parser = SheetParser()
        parser.feed(article)
        if parser.procurement_ref:
            # Store all data for this PO
            result[parser.procurement_ref] = parser.data
    return result

def parse_date(date_str):
    """Convert date strings like 'Sat., April 25, 2026' to '2026-04-25'."""
    # Remove day of week and any trailing periods
    date_str = re.sub(r'^[A-Za-z]+\.?,?\s*', '', date_str)
    try:
        dt = datetime.strptime(date_str, '%B %d, %Y')
        return dt.strftime('%Y-%m-%d')
    except ValueError:
        # Try alternative format if needed
        return None

def parse_amount(amount_str, unit='USD'):
    """Extract numeric amount from strings like 'USD 109,500.00'."""
    if not amount_str:
        return None
    # Remove currency symbol and commas
    match = re.search(r'[\d,]+\.?\d*', amount_str)
    if match:
        num_str = match.group(0).replace(',', '')
        try:
            return float(num_str)
        except ValueError:
            return None
    return None

def parse_quantity(qty_str):
    """Extract numeric quantity from strings like '109 pcs'."""
    if not qty_str:
        return None
    match = re.search(r'(\d+)', qty_str)
    if match:
        try:
            return int(match.group(1))
        except ValueError:
            return None
    return None

def load_all_data(directory):
    """Load and parse all HTML files in the directory."""
    files = {
        'invoices': 'invoices.html',
        'payments': 'payments.html',
        'purchase_orders': 'purchase_orders.html',
        'receipts': 'receipts.html',
        'requisitions': 'requisitions.html',
        'warehouse_scans': 'warehouse_scans.html'
    }

    data = {}
    for doc_name, filename in files.items():
        filepath = os.path.join(directory, filename)
        if os.path.exists(filepath):
            data[doc_name] = parse_html_file(filepath)
        else:
            data[doc_name] = {}
    return data

def extract_fact(data, po, fact_name, rule):
    """Extract a fact for a given PO according to the rule."""
    # Map fact names to document field names
    field_map = {
        'invoice amount': ('invoices', 'Invoice grand total'),
        'order amount': ('purchase_orders', 'Total order value'),
        'quantity received': ('receipts', 'Units counted on delivery'),
        'quantity invoiced': ('invoices', 'Units charged'),
        'goods received': ('receipts', 'Delivery booked'),
        'payment date': ('payments', 'Funds released'),
        'payment due': ('invoices', 'Payment deadline')
    }

    doc_name, field_name = field_map[fact_name]

    # Special handling for goods_received with fallback
    if fact_name == 'goods received':
        # First try receipts
        if po in data['receipts'] and field_name in data['receipts'][po]:
            value = data['receipts'][po][field_name]
            if value and 'left blank' not in value:
                return [parse_date(value), 'receipts']

        # Fallback to warehouse_scans
        if po in data['warehouse_scans'] and 'Dock scanner stamp' in data['warehouse_scans'][po]:
            value = data['warehouse_scans'][po]['Dock scanner stamp']
            if value and 'left blank' not in value:
                return [parse_date(value), 'warehouse_scans']

        # No value found
        return "ABSENT"

    # For other facts
    if po not in data[doc_name]:
        return "ABSENT"

    sheet_data = data[doc_name][po]

    if field_name not in sheet_data:
        return "ABSENT"

    value = sheet_data[field_name]

    # Check for void/blank values
    if 'left blank' in value or 'void' in value.lower():
        return "ABSENT"

    # Parse based on fact type
    if 'amount' in fact_name:
        parsed = parse_amount(value)
        if parsed is None:
            return "ABSENT"
        return [str(parsed), doc_name]
    elif 'quantity' in fact_name:
        parsed = parse_quantity(value)
        if parsed is None:
            return "ABSENT"
        return [str(parsed), doc_name]
    elif 'date' in fact_name or 'due' in fact_name or 'received' in fact_name:
        parsed = parse_date(value)
        if parsed is None:
            return "ABSENT"
        return [parsed, doc_name]

    return "ABSENT"

def check_conflict(data, po, fact_name):
    """Check if there are conflicting values for a fact in the deciding document."""
    # For this case, conflicts only occur if the same PO appears multiple times
    # in the same document with different values for the same field

    field_map = {
        'invoice amount': ('invoices', 'Invoice grand total'),
        'order amount': ('purchase_orders', 'Total order value'),
        'quantity received': ('receipts', 'Units counted on delivery'),
        'quantity invoiced': ('invoices', 'Units charged'),
        'goods received': ('receipts', 'Delivery booked'),
        'payment date': ('payments', 'Funds released'),
        'payment due': ('invoices', 'Payment deadline')
    }

    if fact_name not in field_map:
        return False

    doc_name, field_name = field_map[fact_name]

    # Count unique values for this PO in the document
    values = set()
    for sheet_po, sheet_data in data[doc_name].items():
        if sheet_po == po and field_name in sheet_data:
            value = sheet_data[field_name]
            if 'left blank' not in value and 'void' not in value.lower():
                # Normalize the value for comparison
                if 'amount' in fact_name:
                    parsed = parse_amount(value)
                    if parsed is not None:
