#!/usr/bin/env python3
"""
Extract facts from procurement records based on decision rules.
Takes a directory path as only argument, reads HTML files, outputs JSON.
"""

import sys
import os
import json
import re
from pathlib import Path
from datetime import datetime
from html.parser import HTMLParser
from collections import defaultdict

# ----------------------------------------------------------------------
# Parsing utilities
# ----------------------------------------------------------------------

class SheetParser(HTMLParser):
    """Parse a single sheet/article from the HTML files."""
    def __init__(self):
        super().__init__()
        self.in_table = False
        self.in_th = False
        self.in_td = False
        self.current_label = ""
        self.data = {}
        self.temp_value = []
        self.proc_ref = None

    def handle_starttag(self, tag, attrs):
        if tag == "table" and ("class", "fields") in attrs:
            self.in_table = True
        elif self.in_table and tag == "th":
            self.in_th = True
        elif self.in_table and tag == "td":
            self.in_td = True
            self.temp_value = []

    def handle_endtag(self, tag):
        if tag == "table" and self.in_table:
            self.in_table = False
        elif tag == "th":
            self.in_th = False
        elif tag == "td":
            self.in_td = False
            if self.current_label and self.temp_value:
                value = " ".join(self.temp_value).strip()
                if value and not value.startswith("&mdash;"):
                    self.data[self.current_label] = value
                    if self.current_label == "Procurement reference":
                        # Extract PO number from bold text
                        match = re.search(r'PO-\d+', value)
                        if match:
                            self.proc_ref = match.group(0)
                self.current_label = ""
                self.temp_value = []

    def handle_data(self, data):
        if self.in_th:
            self.current_label = data.strip()
        elif self.in_td:
            self.temp_value.append(data)

def parse_date(date_str):
    """Convert date strings like 'Tue., March 3, 2026' to YYYY-MM-DD."""
    # Remove day of week and any trailing dots
    date_str = re.sub(r'^[A-Za-z]+\.?,?\s*', '', date_str)
    # Standardize month abbreviations
    month_map = {
        'Jan.': 'Jan', 'Feb.': 'Feb', 'Mar.': 'Mar', 'Apr.': 'Apr',
        'May.': 'May', 'Jun.': 'Jun', 'Jul.': 'Jul', 'Aug.': 'Aug',
        'Sep.': 'Sep', 'Oct.': 'Oct', 'Nov.': 'Nov', 'Dec.': 'Dec',
        'March': 'Mar', 'April': 'Apr', 'June': 'Jun', 'July': 'Jul',
        'August': 'Aug', 'Sept.': 'Sep', 'September': 'Sep',
        'October': 'Oct', 'November': 'Nov', 'December': 'Dec'
    }
    for abbr, std in month_map.items():
        date_str = date_str.replace(abbr, std)
    try:
        dt = datetime.strptime(date_str.strip(), '%b %d, %Y')
        return dt.strftime('%Y-%m-%d')
    except ValueError:
        # Try alternative format without comma
        try:
            dt = datetime.strptime(date_str.strip(), '%b %d %Y')
            return dt.strftime('%Y-%m-%d')
        except ValueError:
            return None

def parse_amount(amount_str):
    """Extract decimal number from amount strings like 'USD 114,000.00'."""
    match = re.search(r'[\d,]+\.\d+', amount_str)
    if match:
        return match.group(0).replace(',', '')
    return None

def parse_quantity(qty_str):
    """Extract integer from quantity strings like '129 pcs'."""
    match = re.search(r'(\d+)', qty_str)
    if match:
        return match.group(1)
    return None

# ----------------------------------------------------------------------
# Document reading and indexing
# ----------------------------------------------------------------------

def read_document(file_path):
    """Read an HTML file and extract all sheets."""
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # Split by article tags
    articles = re.findall(r'<article[^>]*>.*?</article>', content, re.DOTALL)
    sheets = []
    for art in articles:
        parser = SheetParser()
        parser.feed(art)
        if parser.proc_ref:
            sheets.append({
                'proc_ref': parser.proc_ref,
                'data': parser.data
            })
    return sheets

def index_sheets_by_proc_ref(sheets):
    """Group sheets by procurement reference."""
    index = defaultdict(list)
    for sheet in sheets:
        index[sheet['proc_ref']].append(sheet)
    return index

# ----------------------------------------------------------------------
# Fact extraction
# ----------------------------------------------------------------------

def extract_invoice_amount(proc_ref, invoices_index):
    """Extract invoice amount from invoices."""
    if proc_ref not in invoices_index:
        return "ABSENT", None
    sheets = invoices_index[proc_ref]
    values = set()
    for sheet in sheets:
        if 'Invoice grand total' in sheet['data']:
            amount = parse_amount(sheet['data']['Invoice grand total'])
            if amount:
                values.add(amount)
    if not values:
        return "ABSENT", None
    if len(values) > 1:
        return "CONFLICT", None
    return list(values)[0], "invoices"

def extract_order_amount(proc_ref, purchase_orders_index):
    """Extract order amount from purchase_orders."""
    if proc_ref not in purchase_orders_index:
        return "ABSENT", None
    sheets = purchase_orders_index[proc_ref]
    values = set()
    for sheet in sheets:
        if 'Total order value' in sheet['data']:
            amount = parse_amount(sheet['data']['Total order value'])
            if amount:
                values.add(amount)
    if not values:
        return "ABSENT", None
    if len(values) > 1:
        return "CONFLICT", None
    return list(values)[0], "purchase_orders"

def extract_quantity_received(proc_ref, receipts_index):
    """Extract quantity received from receipts."""
    if proc_ref not in receipts_index:
        return "ABSENT", None
    sheets = receipts_index[proc_ref]
    values = set()
    for sheet in sheets:
        if 'Units counted on delivery' in sheet['data']:
            qty = parse_quantity(sheet['data']['Units counted on delivery'])
            if qty:
                values.add(qty)
    if not values:
        return "ABSENT", None
    if len(values) > 1:
        return "CONFLICT", None
    return list(values)[0], "receipts"

def extract_quantity_invoiced(proc_ref, invoices_index):
    """Extract quantity invoiced from invoices."""
    if proc_ref not in invoices_index:
        return "ABSENT", None
    sheets = invoices_index[proc_ref]
    values = set()
    for sheet in sheets:
        if 'Units charged' in sheet['data']:
            qty = parse_quantity(sheet['data']['Units charged'])
            if qty:
                values.add(qty)
    if not values:
        return "ABSENT", None
    if len(values) > 1:
        return "CONFLICT", None
    return list(values)[0], "invoices"

def extract_goods_received(proc_ref, receipts_index, warehouse_scans_index):
    """Extract goods received date from receipts, fallback to warehouse_scans."""
    # Try receipts first
    if proc_ref in receipts_index:
        sheets = receipts_index[proc_ref]
        values = set()
        for sheet in sheets:
            if 'Delivery booked' in sheet['data']:
                date = parse_date(sheet['data']['Delivery booked'])
                if date:
                    values.add(date)
        if values:
            if len(values) > 1:
                return "CONFLICT", None
            return list(values)[0], "receipts"

    # Fallback to warehouse_scans
    if proc_ref in warehouse_scans_index:
        sheets = warehouse_scans_index[proc_ref]
        values = set()
        for sheet in sheets:
            if 'Dock scanner stamp' in sheet['data']:
                date = parse_date(sheet['data']['Dock scanner stamp'])
                if date:
                    values.add(date)
        if values:
            if len(values) > 1:
                return "CONFLICT", None
            return list(values)[0], "warehouse_scans"

    return "ABSENT", None

def extract_payment_date(proc_ref, payments_index):
    """Extract payment date from payments."""
    if proc_ref not in payments_index:
        return "ABSENT", None
    sheets = payments_index[proc_ref]
    values = set()
    for sheet in sheets:
