            if date:
                values.add(date)
    if not values:
        return "ABSENT", None
    if len(values) > 1:
        return "CONFLICT", None
    return list(values)[0], "payments"

def extract_payment_due(proc_ref, invoices_index):
    """Extract payment due date from invoices."""
    if proc_ref not in invoices_index:
