def parse_sql_file(file_path: Path) -> List[Dict]:
    """Parse SQL INSERT statements and return list of records."""
    records = []
    try:
        content = file_path.read_text(encoding='utf-8')
    except Exception as e:
        print(f"Error reading {file_path}: {e}", file=sys.stderr)
        return records

    # Find all INSERT statements
    insert_pattern = r'INSERT INTO \w+ \([^)]+\) VALUES\s*(\([^)]*(?:\)\s*,\s*\([^)]*)*\));'
    matches = re.findall(insert_pattern, content, re.IGNORECASE | re.DOTALL)

    for match in matches:
        # Split into individual value tuples
        tuples = re.findall(r'\([^)]+\)', match)
        for tup in tuples:
            # Remove parentheses and split by comma
            values = tup.strip('()').split(',')
            # Clean values
            cleaned = []
            for v in values:
                v = v.strip()
                if v.upper() == 'NULL':
                    cleaned.append(None)
                elif v.isdigit() or (v.startswith('-') and v[1:].isdigit()):
                    cleaned.append(int(v))
                elif re.match(r'^-?\d+\.\d+$', v):
                    cleaned.append(float(v))
                else:
                    # Remove quotes
                    if (v.startswith("'") and v.endswith("'")) or (v.startswith('"') and v.endswith('"')):
                        v = v[1:-1]
                    cleaned.append(v)

            # Get column names from INSERT statement
            col_match = re.search(r'INSERT INTO \w+ \(([^)]+)\)', match, re.IGNORECASE)
            if col_match:
                columns = [col.strip() for col in col_match.group(1).split(',')]
                if len(columns) == len(cleaned):
                    records.append(dict(zip(columns, cleaned)))

    return records

def epoch_to_date(epoch_day: int) -> str:
    """Convert epoch day to YYYY-MM-DD string."""
    base_date = datetime(1970, 1, 1)
    target_date = base_date + timedelta(days=epoch_day)
    return target_date.strftime('%Y-%m-%d')

