import sys
import os
import json
import re
from datetime import datetime, timedelta
from collections import defaultdict

def parse_sql_file(filepath):
    """Parse SQL file to extract table data."""
    data = []
    with open(filepath, 'r') as f:
        content = f.read()

    # Find INSERT statements
    insert_pattern = r'INSERT INTO \w+ \([^)]+\) VALUES\s*(\([^)]*(?:\)\s*,\s*\([^)]*)*\));'
    matches = re.findall(insert_pattern, content, re.IGNORECASE | re.DOTALL)

    for match in matches:
        # Split into individual rows
        rows = match.strip().split('),')
        for row in rows:
            row = row.strip()
            if row.startswith('('):
                row = row[1:]
            if row.endswith(')'):
                row = row[:-1]
            if row.endswith(');'):
                row = row[:-2]

            # Parse values
            values = []
            current = ''
            in_string = False
            for char in row:
                if char == "'" and not in_string:
                    in_string = True
                elif char == "'" and in_string:
                    in_string = False
                elif char == ',' and not in_string:
                    values.append(current.strip())
                    current = ''
                    continue
                current += char
            if current:
                values.append(current.strip())

            # Convert NULL to None
            processed_values = []
            for v in values:
                if v.upper() == 'NULL':
                    processed_values.append(None)
                else:
                    # Remove quotes if present
                    if v.startswith("'") and v.endswith("'"):
                        v = v[1:-1]
                    processed_values.append(v)

            if processed_values:
                data.append(processed_values)

    return data

def parse_table_structure(filepath):
    """Parse table structure to get column names."""
    with open(filepath, 'r') as f:
        content = f.read()

    # Find CREATE TABLE statement
    create_pattern = r'CREATE TABLE (\w+) \((.*?)\);'
    match = re.search(create_pattern, content, re.DOTALL | re.IGNORECASE)
    if not match:
        return []

    columns_section = match.group(2)
    lines = columns_section.split('\n')
    columns = []
    for line in lines:
        line = line.strip().strip(',')
        if line and not line.upper().startswith('PRIMARY KEY') and not line.upper().startswith('FOREIGN KEY'):
            parts = line.split()
            if parts:
                columns.append(parts[0])

    return columns

def load_document_data(dir_path, filename):
    """Load and parse a document file."""
    filepath = os.path.join(dir_path, filename)
    if not os.path.exists(filepath):
        return []

    columns = parse_table_structure(filepath)
    rows = parse_sql_file(filepath)

    # Group by ord_code
    data_by_code = defaultdict(list)
    for row in rows:
        if len(row) != len(columns):
            continue

        record = dict(zip(columns, row))
        ord_code = record.get('ord_code')
        if ord_code:
            data_by_code[ord_code].append(record)

    return data_by_code

def epoch_to_date(epoch_day):
    """Convert epoch day to YYYY-MM-DD string."""
    if epoch_day is None:
        return None
    try:
        epoch_day = int(epoch_day)
        base_date = datetime(1970, 1, 1)
        target_date = base_date + timedelta(days=epoch_day)
        return target_date.strftime('%Y-%m-%d')
    except:
        return None

def cents_to_usd(cents):
    """Convert cents to USD decimal string."""
    if cents is None:
        return None
    try:
        dollars = float(cents) / 100.0
        # Format with 2 decimal places, removing trailing zeros
        return f"{dollars:.2f}".rstrip('0').rstrip('.')
    except:
        return None

def get_invoice_amount(invoices_data, ord_code):
    """Get invoice amount from invoices data."""
    if ord_code not in invoices_data:
        return None, None

    records = invoices_data[ord_code]
