import json
import os
import sys
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

def parse_edi_file(file_path: Path) -> Dict[str, List[Dict]]:
    """
    Parse an EDI file and return a dictionary mapping PO numbers to lists of records.
    Each record is a dict with fields: vendor_id, plant, and relevant values.
    """
    data = {}
    current_po = None
    current_record = {}

    with open(file_path, 'r', encoding='utf-8') as f:
        lines = f.readlines()

    in_lx = False
    for line in lines:
        segments = line.strip().split('~')
        for segment in segments:
            if not segment:
                continue

            elements = segment.split('*')
            seg_id = elements[0]

            if seg_id == 'LX':
                # Save previous record
                if current_po and current_record:
                    if current_po not in data:
                        data[current_po] = []
                    data[current_po].append(current_record)

                # Start new record
                current_po = None
                current_record = {}
                in_lx = True

            elif in_lx and seg_id == 'REF':
                if len(elements) >= 3 and elements[1] == 'PO':
                    current_po = elements[2]

            elif in_lx and seg_id == 'N1':
                if len(elements) >= 3:
                    qualifier = elements[1]
                    if qualifier == 'VN':
                        # Vendor name and ID
                        vendor_name = elements[2] if len(elements) > 2 else ''
                        vendor_id = elements[4] if len(elements) > 4 else ''
                        current_record['vendor_id'] = vendor_id
                    elif qualifier == 'ST':
                        plant = elements[2] if len(elements) > 2 else ''
                        current_record['plant'] = plant

            elif in_lx and seg_id == 'TDS':
                if len(elements) >= 2:
                    # TDS has implied 2 decimal places
                    try:
                        value = int(elements[1])
                        current_record['tds'] = value / 100.0
                    except (ValueError, IndexError):
                        pass

            elif in_lx and seg_id == 'AMT':
                if len(elements) >= 3:
                    qualifier = elements[1]
                    try:
                        value = float(elements[2])
                        if qualifier == 'TT':
                            current_record['order_amount'] = value
                        elif qualifier == 'EST':
                            current_record['estimated_amount'] = value
                    except (ValueError, IndexError):
                        pass

            elif in_lx and seg_id == 'QTY':
                if len(elements) >= 3:
                    qualifier = elements[1]
                    try:
                        value = int(elements[2])
                        if qualifier == 'D1':
                            current_record['quantity_invoiced'] = value
                        elif qualifier == 'RC':
                            current_record['quantity_received'] = value
                    except (ValueError, IndexError):
                        pass

            elif in_lx and seg_id == 'DTP':
                if len(elements) >= 4:
                    qualifier = elements[1]
                    date_str = elements[3]
                    if len(date_str) == 8:
                        # Format as YYYY-MM-DD
                        formatted_date = f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"

                        if qualifier == '481':
                            current_record['payment_due'] = formatted_date
                        elif qualifier == '234':
                            current_record['payment_date'] = formatted_date
                        elif qualifier == '050':
                            current_record['goods_received'] = formatted_date
                        elif qualifier == '945':
                            current_record['warehouse_scan'] = formatted_date
                        elif qualifier == '002':
                            current_record['delivery_requested'] = formatted_date
                        elif qualifier == '097':
                            current_record['transaction_created'] = formatted_date

    # Add the last record
    if current_po and current_record:
        if current_po not in data:
            data[current_po] = []
        data[current_po].append(current_record)

    return data

def extract_fact(
    po: str,
    fact_name: str,
    documents: Dict[str, Dict[str, List[Dict]]],
    rule_docs: List[str],
    fallback_doc: Optional[str] = None
) -> Union[List[str], str]:
    """
    Extract a fact for a given PO according to decision rules.
    Returns either ["value", "document"] or "ABSENT" or "CONFLICT".
    """
    values = {}

    # Check each document in order
    for doc_name in rule_docs:
        if doc_name in documents and po in documents[doc_name]:
            records = documents[doc_name][po]

            # Extract value based on fact name
            for record in records:
                if fact_name == 'invoice amount':
                    if 'tds' in record:
                        value = f"{record['tds']:.2f}"
                        if doc_name not in values:
                            values[doc_name] = value
                        elif values[doc_name] != value:
                            return "CONFLICT"
                elif fact_name == 'order amount':
                    if 'order_amount' in record:
                        value = f"{record['order_amount']:.2f}"
                        if doc_name not in values:
                            values[doc_name] = value
                        elif values[doc_name] != value:
                            return "CONFLICT"
                elif fact_name == 'quantity received':
                    if 'quantity_received' in record:
                        value = str(record['quantity_received'])
                        if doc_name not in values:
                            values[doc_name] = value
                        elif values[doc_name] != value:
                            return "CONFLICT"
                elif fact_name == 'quantity invoiced':
                    if 'quantity_invoiced' in record:
                        value = str(record['quantity_invoiced'])
                        if doc_name not in values:
                            values[doc_name] = value
                        elif values[doc_name] != value:
                            return "CONFLICT"
                elif fact_name == 'goods received':
                    if 'goods_received' in record:
                        value = record['goods_received']
                        if doc_name not in values:
                            values[doc_name] = value
                        elif values[doc_name] != value:
                            return "CONFLICT"
                elif fact_name == 'payment date':
                    if 'payment_date' in record:
                        value = record['payment_date']
                        if doc_name not in values:
                            values[doc_name] = value
                        elif values[doc_name] != value:
                            return "CONFLICT"
                elif fact_name == 'payment due':
                    if 'payment_due' in record:
                        value = record['payment_due']
                        if doc_name not in values:
                            values[doc_name] = value
                        elif values[doc_name] != value:
                            return "CONFLICT"

    # Check fallback document if no value found
    if not values and fallback_doc:
        if fallback_doc in documents and po in documents[fallback_doc]:
            records = documents[fallback_doc][po]
            for record in records:
                if fact_name == 'goods received':
                    if 'warehouse_scan' in record:
                        value = record['warehouse_scan']
                        if fallback_doc not in values:
                            values[fallback_doc] = value
                        elif values[fallback_doc] != value:
                            return "CONFLICT"

    # Determine result
    if not values:
        return "ABSENT"

    # Get the first document that has a value
    for doc_name in rule_docs:
        if doc_name in values:
            return [values[doc_name], doc_name]

    # Check fallback
    if fallback_doc and fallback_doc in values:
        return [values[fallback_doc], fallback_doc]

    return "ABSENT"

def main(directory_path: str):
    # Parse all EDI files
    documents = {}
    file_mapping = {
        'invoices': 'invoices.edi',
