```python
import json
import os
import re
import sys
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

def parse_edi_file(file_path: Path) -> List[Dict]:
    """Parse EDI file and return list of records (each record is a dict)."""
    records = []
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # Split by LX segments to get individual records
    # Each record starts with LX and goes until next LX or end of transaction
    lx_pattern = r'LX\*(\d+)~'
    lx_matches = list(re.finditer(lx_pattern, content))

    for i, match in enumerate(lx_matches):
        start_pos = match.start()
        if i + 1 < len(lx_matches):
            end_pos = lx_matches[i + 1].start()
        else:
            end_pos = len(content)

        record_text = content[start_pos:end_pos]
        record = {'LX': match.group(1)}

        # Extract REF*PO (purchase order number)
        po_match = re.search(r'REF\*PO\*([^~]+)~', record_text)
        if po_match:
            record['PO'] = po_match.group(1)

        # Extract vendor info: N1*VN*<name>*92*<vendor_id>
        vn_match = re.search(r'N1\*VN\*([^*]+)\*92\*([^~]+)~', record_text)
        if vn_match:
            record['VENDOR_NAME'] = vn_match.group(1).strip()
            record['VENDOR_ID'] = vn_match.group(2)

        # Extract ship-to plant: N1*ST*<plant>
        st_match = re.search(r'N1\*ST\*([^~]+)~', record_text)
        if st_match:
            record['PLANT'] = st_match.group(1).strip()

        # Extract amounts and quantities based on file type
        if 'invoices' in str(file_path):
            # TDS*<amount> (implied 2 decimal places)
            tds_match = re.search(r'TDS\*(\d+)~', record_text)
            if tds_match:
                amount = int(tds_match.group(1))
                record['INVOICE_AMOUNT'] = f"{amount / 100:.2f}"

            # QTY*D1*<quantity>*EA (quantity invoiced)
            qty_match = re.search(r'QTY\*D1\*(\d+)\*EA~', record_text)
            if qty_match:
                record['QUANTITY_INVOICED'] = qty_match.group(1)

            # DTP*481*D8*<date> (payment due date)
            dtp_match = re.search(r'DTP\*481\*D8\*(\d{8})~', record_text)
            if dtp_match:
                date_str = dtp_match.group(1)
                record['PAYMENT_DUE'] = f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"

        elif 'payments' in str(file_path):
            # DTP*234*D8*<date> (payment date)
            dtp_match = re.search(r'DTP\*234\*D8\*(\d{8})~', record_text)
            if dtp_match:
                date_str = dtp_match.group(1)
                record['PAYMENT_DATE'] = f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"

        elif 'purchase_orders' in str(file_path):
            # AMT*TT*<amount> (explicit decimal)
            amt_match = re.search(r'AMT\*TT\*([\d.]+)~', record_text)
            if amt_match:
                record['ORDER_AMOUNT'] = amt_match.group(1)

        elif 'receipts' in str(file_path):
            # QTY*RC*<quantity>*EA (quantity received)
            qty_match = re.search(r'QTY\*RC\*(\d+)\*EA~', record_text)
            if qty_match:
                record['QUANTITY_RECEIVED'] = qty_match.group(1)

            # DTP*050*D8*<date> (goods received date)
            dtp_match = re.search(r'DTP\*050\*D8\*(\d{8})~', record_text)
            if dtp_match:
                date_str = dtp_match.group(1)
                record['GOODS_RECEIVED'] = f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"

        elif 'warehouse_scans' in str(file_path):
            # DTP*945*D8*<date> (warehouse scan date)
            dtp_match = re.search(r'DTP\*945\*D8\*(\d{8})~', record_text)
            if dtp_match:
                date_str = dtp_match.group(1)
                record['WAREHOUSE_SCAN_DATE'] = f"{date_str[:4]}-{date_str[4:6]}-{date_str[6:8]}"

        # Extract REF*ZZ (source token) for debugging if needed
        zz_match = re.search(r'REF\*ZZ\*([^~]+)~', record_text)
        if zz_match:
            record['ZZ'] = zz_match.group(1)

        records.append(record)

    return records

def extract_facts_from_documents(directory: Path) -> Dict[str, Dict]:
    """Extract all facts from all documents in the directory."""
    facts = {
        'invoices': {},
        'payments': {},
        'purchase_orders': {},
        'receipts': {},
        'warehouse_scans': {},
        'requisitions': {}  # Not used in rules but present in files
    }

    # Map file names to keys
    file_map = {
        'invoices.edi': 'invoices',
        'payments.edi': 'payments',
        'purchase_orders.edi': 'purchase_orders',
        'receipts.edi': 'receipts',
        'warehouse_scans.edi': 'warehouse_scans',
        'requisitions.edi': 'requisitions'
    }

    for file_name, key in file_map.items():
        file_path = directory / file_name
        if file_path.exists():
            records = parse_edi_file(file_path)
            for record in records:
                if 'PO' in record:
                    po = record['PO']
                    if po not in facts[key]:
                        facts[key][po] = []
                    facts[key][po].append(record)

    return facts

def get_fact_value(facts: Dict, po: str, fact_name: str, rule_type: str) -> Union[List, str]:
    """Get fact value according to decision rules."""

    if rule_type == 'pa.three_way_match':
        if fact_name == 'invoice amount':
            # Only from invoices
            if po in facts['invoices']:
                records = facts['invoices'][po]
                values = set()
                for rec in records:
                    if 'INVOICE_AMOUNT' in rec:
                        values.add(rec['INVOICE_AMOUNT'])
                if len(values) == 0:
                    return "ABSENT"
                elif len(values) == 1:
                    return [list(values)[0], 'invoices']
                else:
                    return "CONFLICT"
            return "ABSENT"

        elif fact_name == 'order amount':
            # Only from purchase_orders
            if po in facts['purchase_orders']:
                records = facts['purchase_orders'][po]
                values = set()
                for rec in records:
                    if 'ORDER_AMOUNT' in rec:
                        values.add(rec['ORDER_AMOUNT'])
                if len(values) == 0:
                    return "ABSENT"
                elif len(values) == 1:
                    return [list(values)[0], 'purchase_orders']
                else:
                    return "CONFLICT"
            return "ABSENT"

        elif fact_name == 'quantity received':
            # Only from receipts
            if po in facts['receipts']:
                records = facts['receipts'][po]
                values = set()
                for rec in records:
                    if 'QUANTITY_RECEIVED' in rec:
                        values.add(rec['QUANTITY_RECEIVED'])
                if len(values) == 0:
                    return "ABSENT"
                elif len(values) == 1:
                    return [list(values)[0], 'receipts']
                else:
                    return "CONFLICT"
            return "ABSENT"

        elif fact_name == 'quantity invoiced':
            # Only from invoices
            if po in facts['invoices']:
                records = facts['invoices'][po]
                values = set()
                for rec in records:
                    if 'QUANTITY_INVOICED' in rec:
                        values.add(rec['QUANTITY_INVOICED'])
                if len(values) == 0:
                    return "ABSENT"
                elif len(values) == 1:
                    return [list(values)[0], 'invoices']
                else:
                    return "CONFLICT"
            return "ABSENT"

    elif rule_type == 'pa.paid_in_window':
        if fact_name == 'goods received':
            # First try receipts, then warehouse_scans
            if po in facts['receipts']:
                records = facts['receipts'][po]
                values = set()
                for rec in records:
                    if 'GOODS_RECEIVED' in rec:
                        values.add(rec['GOODS_RECEIVED'])
                if len(values) == 0:
                    # Try warehouse_scans
                    if po in facts['warehouse_scans']:
                        records = facts['warehouse_scans'][po]
                        values = set()
                        for rec in records:
                            if 'WAREHOUSE_SCAN_DATE' in rec:
                                values.add(rec['WAREHOUSE_SCAN_DATE'])
                        if len(values) == 0:
                            return "ABSENT"
                        elif len(values) == 1:
                            return [list(values)[0], 'warehouse_scans']
                        else:
                            return "CONFLICT"
                    return "ABSENT"
                elif len(values) == 1:
                    return [list(values)[0], 'receipts']
                else:
                    return "CONFLICT"
            else:
                # Try warehouse_scans directly
                if po in facts['warehouse_scans']:
                    records = facts['warehouse_scans'][po]
                    values = set()
                    for rec in records:
                        if 'WAREHOUSE_SCAN_DATE' in rec:
                            values.add(rec['WAREHOUSE_SCAN_DATE'])
                    if len(values) == 0:
                        return "ABSENT"
                    elif len(values) == 1:
                        return [list(values)[0], 'warehouse_scans']
                    else:
                        return "CONFLICT"
                return "ABSENT"

        elif fact_name == 'payment date':
            # Only from payments
            if po in facts['payments']:
                records = facts['payments'][po]
                values = set()
                for rec in records:
                    if 'PAYMENT_DATE' in rec:
                        values.add(rec['PAYMENT_DATE'])
                if len(values) == 0:
                    return "ABSENT"
                elif len(values) == 1:
                    return [list(values)[0], 'payments']
                else:
                    return "CONFLICT"
            return "ABSENT"

        elif fact_name == 'payment due':
            # Only from invoices
            if po in facts['invoices']:
                records = facts['invoices'][po]
                values = set()
                for rec in records:
                    if 'PAYMENT_DUE' in rec:
                        values.add(rec['PAYMENT_DUE'])
                if len(values) == 0:
                    return "ABSENT"
                elif len(values) == 1:
                    return [list(values)[0], 'invoices']
                else:
                    return "CONFLICT"
            return "ABSENT"

    return "ABSENT"

def main():
    if len(sys.argv) != 2:
        print("Usage: python extractor.py <directory_path>")
        sys.exit(1)

    directory = Path(sys.argv[1])
    if not directory.exists() or not directory.is_dir():
        print(f"Error: Directory '{directory}' does not exist or is not a directory")
        sys.exit(1)

    # Extract facts from all documents
    facts = extract_facts_from_documents(directory)

