import json
import re
import sys
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Union

def parse_mailbox_file(file_path: Path) -> List[Dict]:
    """Parse a mailbox export file into a list of messages."""
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()

    # Split by message separator
    messages = []
    sections = content.split('=' * 72)

    for section in sections:
        section = section.strip()
        if not section:
            continue

        # Extract PO number from subject
        po_match = re.search(r'PO-\d+', section)
        if not po_match:
            continue

        po_number = po_match.group(0)

        # Extract amount values
        amount_patterns = [
            r'\$([\d,]+(?:\.\d{2})?)',  # $12,345.67
            r'([\d,]+(?:\.\d{2})?) dollars',  # 12,345 dollars
            r'([\d,]+(?:\.\d{2})?) dollars in total',
            r'([\d,]+(?:\.\d{2})?) dollars all-in',
            r'([\d,]+(?:\.\d{2})?) dollars all told',
            r'([\d,]+(?:\.\d{2})?) dollars overall',
            r'([\d,]+(?:\.\d{2})?) dollars? in total',
            r'total is ([$\d,]+(?:\.\d{2})?)',
            r'comes to ([$\d,]+(?:\.\d{2})?)',
            r'is ([$\d,]+(?:\.\d{2})?) all told',
            r'raised for ([$\d,]+(?:\.\d{2})?)',
            r'ask.*was ([$\d,]+(?:\.\d{2})?)',
            r'asked for ([$\d,]+(?:\.\d{2})?)',
            r'value.*is ([$\d,]+(?:\.\d{2})?) overall',
            r'Committed value.*is ([$\d,]+(?:\.\d{2})?) overall',
            r'Budget ask.*was ([$\d,]+(?:\.\d{2})?)',
        ]

        amount = None
        for pattern in amount_patterns:
            match = re.search(pattern, section, re.IGNORECASE)
            if match:
                amount_str = match.group(1).replace('$', '').replace(',', '')
                try:
                    # Check if it's a decimal
                    if '.' in amount_str:
                        amount = float(amount_str)
                    else:
                        amount = int(amount_str)
                    break
                except ValueError:
                    continue

        # Extract quantity values
        quantity_patterns = [
            r'(\d+)\s*(?:units|pieces|pieces on arrival|units on arrival|units off the truck|pieces off the truck)',
            r'charged us for (\d+)\s*(?:pieces|units)',
            r'lists (\d+)\s*(?:units|pieces) as',
            r'counted (\d+)\s*(?:pieces|units) on arrival',
            r'tallied (\d+)\s*(?:units|pieces) off the truck',
            r'(\d+)\s*(?:units|pieces) as the chargeable count',
        ]

        quantity = None
        for pattern in quantity_patterns:
            match = re.search(pattern, section, re.IGNORECASE)
            if match:
                try:
                    quantity = int(match.group(1))
                    break
                except ValueError:
                    continue

        # Extract dates
        date_patterns = [
            r'(\d{1,2})(?:st|nd|rd|th)?\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{4})',
            r'(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{1,2})(?:st|nd|rd|th)?,?\s+(\d{4})',
            r'(\d{4})-(\d{2})-(\d{2})',
            r'(\d{1,2})/(\d{1,2})/(\d{4})',
        ]

        date = None
        for pattern in date_patterns:
            matches = re.findall(pattern, section, re.IGNORECASE)
            for match in matches:
                if len(match) == 3:
                    if match[0].isalpha():  # Month Day Year
                        month_str, day_str, year_str = match
                    else:  # Day Month Year
                        day_str, month_str, year_str = match

                    month_map = {
                        'jan': '01', 'feb': '02', 'mar': '03', 'apr': '04',
                        'may': '05', 'jun': '06', 'jul': '07', 'aug': '08',
                        'sep': '09', 'oct': '10', 'nov': '11', 'dec': '12'
                    }

                    month = month_map.get(month_str.lower()[:3])
                    day = day_str.zfill(2)
                    year = year_str

                    date = f"{year}-{month}-{day}"
                    break
            if date:
                break

        # Check for "no value" indicators
        no_value_indicators = [
            "I have no",
            "doesn't show",
            "don't have",
            "no payment deadline",
            "no booking-in day",
            "no release-of-funds day",
        ]

        has_no_value = any(indicator in section for indicator in no_value_indicators)

        messages.append({
            'po': po_number,
            'amount': amount,
            'quantity': quantity,
            'date': date,
            'has_no_value': has_no_value,
            'raw': section[:200]  # Store first 200 chars for debugging
        })

    return messages

def extract_facts(directory: Path) -> Dict[str, Dict]:
    """Extract all facts from all files in the directory."""
    files = {
        'invoices': directory / 'invoices.txt',
        'payments': directory / 'payments.txt',
        'purchase_orders': directory / 'purchase_orders.txt',
        'receipts': directory / 'receipts.txt',
        'requisitions': directory / 'requisitions.txt',
        'warehouse_scans': directory / 'warehouse_scans.txt',
    }

    all_data = {}
    for doc_type, file_path in files.items():
        if file_path.exists():
            all_data[doc_type] = parse_mailbox_file(file_path)
        else:
            all_data[doc_type] = []

    # Organize by PO number
    po_data = {}

    for doc_type, messages in all_data.items():
        for msg in messages:
            po = msg['po']
            if po not in po_data:
                po_data[po] = {}
            if doc_type not in po_data[po]:
                po_data[po][doc_type] = []
            po_data[po][doc_type].append(msg)

    return po_data

def get_invoice_amount(po_data: Dict, po: str) -> Union[List, str]:
    """Get invoice amount from invoices."""
    if po not in po_data or 'invoices' not in po_data[po]:
        return "ABSENT"

    invoices = po_data[po]['invoices']
    if not invoices:
        return "ABSENT"

    amounts = []
    for inv in invoices:
        if inv['amount'] is not None:
            amounts.append((str(inv['amount']), "invoices"))

    if not amounts:
        return "ABSENT"

    # Check for conflicts
    unique_amounts = set(amount for amount, _ in amounts)
    if len(unique_amounts) > 1:
        return "CONFLICT"

    return [amounts[0][0], amounts[0][1]]

