import json
import os
import re
import sys
from datetime import datetime
from typing import Dict, List, Optional, Tuple, Union

def parse_date(text: str) -> Optional[str]:
    """Parse various date formats to YYYY-MM-DD."""
    if not text:
        return None
    # Remove ordinal suffixes and common phrases
    text = text.lower().strip()
    text = re.sub(r'(st|nd|rd|th)', '', text)

    # Common patterns
    patterns = [
        r'(\d{1,2})\s+(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{4})',
        r'(\d{1,2})\s+(?:January|February|March|April|May|June|July|August|September|October|November|December)[a-z]*\s+(\d{4})',
        r'(\d{4})-(\d{2})-(\d{2})',
        r'(\d{1,2})/(\d{1,2})/(\d{4})',
    ]

    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            if pattern.startswith(r'(\d{1,2})\s+(?:Jan'):
                day, year = match.groups()
                month_str = re.search(r'(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)', text, re.IGNORECASE)
                if month_str:
                    month_map = {
                        'jan': '01', 'feb': '02', 'mar': '03', 'apr': '04',
                        'may': '05', 'jun': '06', 'jul': '07', 'aug': '08',
                        'sep': '09', 'oct': '10', 'nov': '11', 'dec': '12'
                    }
                    month = month_map[month_str.group().lower()[:3]]
                    return f"{year}-{month}-{int(day):02d}"
            elif pattern.startswith(r'(\d{1,2})\s+(?:January'):
                day, year = match.groups()
                month_str = re.search(r'(January|February|March|April|May|June|July|August|September|October|November|December)', text, re.IGNORECASE)
                if month_str:
                    month_map = {
                        'january': '01', 'february': '02', 'march': '03', 'april': '04',
                        'may': '05', 'june': '06', 'july': '07', 'august': '08',
                        'september': '09', 'october': '10', 'november': '11', 'december': '12'
                    }
                    month = month_map[month_str.group().lower()]
                    return f"{year}-{month}-{int(day):02d}"
            elif pattern == r'(\d{4})-(\d{2})-(\d{2})':
                year, month, day = match.groups()
                return f"{year}-{month}-{day}"
            elif pattern == r'(\d{1,2})/(\d{1,2})/(\d{4})':
                month, day, year = match.groups()
                return f"{year}-{int(month):02d}-{int(day):02d}"

    # Try patterns like "4th Feb 2026"
    match = re.search(r'(\d{1,2})\w+\s+(?:of\s+)?(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\s+(\d{4})', text, re.IGNORECASE)
    if match:
        day, year = match.groups()
        month_str = re.search(r'(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)', text, re.IGNORECASE)
        if month_str:
            month_map = {
                'jan': '01', 'feb': '02', 'mar': '03', 'apr': '04',
                'may': '05', 'jun': '06', 'jul': '07', 'aug': '08',
                'sep': '09', 'oct': '10', 'nov': '11', 'dec': '12'
            }
            month = month_map[month_str.group().lower()[:3]]
            return f"{year}-{month}-{int(day):02d}"

    return None

def parse_amount(text: str) -> Optional[str]:
    """Parse currency amounts to decimal string."""
    if not text:
        return None
    # Remove currency symbols and commas
    text = re.sub(r'[$,]', '', text)
    # Extract numbers with optional decimal
    match = re.search(r'(\d+(?:\.\d+)?)', text)
    if match:
        # Ensure it's a proper decimal string
        amount = match.group(1)
        if '.' in amount:
            return amount
        else:
            return f"{amount}.00"
    return None

def parse_quantity(text: str) -> Optional[str]:
    """Parse quantity numbers."""
    if not text:
        return None
    # Extract first number
    match = re.search(r'(\d+)', text)
    if match:
        return match.group(1)
    return None

class DocumentParser:
    def __init__(self, file_path: str):
        self.file_path = file_path
        self.doc_name = os.path.basename(file_path).replace('.txt', '')
        self.messages = self._parse_messages()

    def _parse_messages(self) -> List[Dict]:
        """Parse the mailbox export format into individual messages."""
        with open(self.file_path, 'r', encoding='utf-8') as f:
            content = f.read()

        messages = []
        # Split by message separator
        parts = content.split('=' * 72)

        for part in parts:
            if not part.strip():
                continue

            # Extract PO number from subject
            po_match = re.search(r'PO-(\d+)', part, re.IGNORECASE)
            po_number = f"PO-{po_match.group(1)}" if po_match else None

            if not po_number:
                continue

            message = {
                'po': po_number,
                'content': part,
                'subject': self._extract_field(part, 'Subject:'),
                'date': self._extract_field(part, 'Date:'),
                'message_id': self._extract_field(part, 'Message-ID:')
            }
            messages.append(message)

        return messages

    def _extract_field(self, text: str, field: str) -> Optional[str]:
        """Extract a field value from message text."""
        lines = text.split('\n')
        for i, line in enumerate(lines):
            if line.startswith(field):
                return line[len(field):].strip()
        return None

    def extract_invoice_amount(self, po: str) -> Tuple[Optional[str], str]:
        """Extract invoice amount for a PO."""
        values = []
        for msg in self.messages:
            if msg['po'] == po:
                content = msg['content'].lower()
                # Look for amount patterns
                patterns = [
                    r'invoice total is (\$?[\d,]+(?:\.\d+)?)',
                    r'bill comes to (\$?[\d,]+(?:\.\d+)?)',
                    r'bill total is (\$?[\d,]+(?:\.\d+)?)',
                    r'total is (\$?[\d,]+(?:\.\d+)?)',
                    r'comes to (\$?[\d,]+(?:\.\d+)?)'
                ]
                for pattern in patterns:
                    match = re.search(pattern, content)
                    if match:
                        amount = parse_amount(match.group(1))
                        if amount:
                            values.append((amount, self.doc_name))
                            break

        if not values:
            return None, self.doc_name
        elif len(set(v[0] for v in values)) == 1:
            return values[0][0], values[0][1]
        else:
            return "CONFLICT", self.doc_name

    def extract_invoice_quantity(self, po: str) -> Tuple[Optional[str], str]:
        """Extract invoiced quantity for a PO."""
        values = []
        for msg in self.messages:
            if msg['po'] == po:
                content = msg['content'].lower()
                # Look for quantity patterns
                patterns = [
                    r'charged us for (\d+)',
                    r'bill lists (\d+)',
                    r'(\d+) (?:units|pieces)',
                    r'count.*?(\d+)',
                    r'(\d+) as the chargeable'
                ]
                for pattern in patterns:
                    match = re.search(pattern, content)
                    if match:
                        qty = parse_quantity(match.group(1))
                        if qty:
                            values.append((qty, self.doc_name))
                            break

        if not values:
            return None, self.doc_name
        elif len(set(v[0] for v in values)) == 1:
            return values[0][0], values[0][1]
        else:
            return "CONFLICT", self.doc_name

    def extract_invoice_due_date(self, po: str) -> Tuple[Optional[str], str]:
        """Extract payment due date for a PO."""
        values = []
        for msg in self.messages:
            if msg['po'] == po:
                content = msg['content']
                # Look for due date patterns
                patterns = [
                    r'payment has to go out by (.*?)\d',
                    r'bill must be settled no later than (.*?)\d',
                    r'payment due (.*?)\d',
                    r'due by (.*?)\d',
                    r'by (.*?)\d{4}'
                ]
                for pattern in patterns:
                    match = re.search(pattern, content, re.IGNORECASE)
