    # Find first non-comment line (header)
    header_line = None
    for line in lines:
        if not line.startswith('#'):
            header_line = line.strip()
            break

    if not header_line:
        return data

    headers = [h.strip() for h in header_line.split(delimiter)]

    # Process remaining non-comment lines
    for line in lines:
        if line.startswith('#') or line.strip() == header_line:
            continue
        parts = [p.strip() for p in line.strip().split(delimiter)]
        if len(parts) != len(headers):
            continue
        record = dict(zip(headers, parts))
        data.append(record)

    return data

def parse_date(date_str):
    """Parse MM/DD/YYYY date string to YYYY-MM-DD format."""
    if not date_str:
