        return data

    col_names = header.split(delimiter)

    # Process data lines
    for line in lines:
        if line.startswith('#') or line.strip() == header:
            continue
        if line.strip():
            values = line.strip().split(delimiter)
            # Pad values if needed
            while len(values) < len(col_names):
                values.append('')
            row = dict(zip(col_names, values))
            data.append(row)

