import sys
import os
import json
import re
from datetime import datetime
from html.parser import HTMLParser
from collections import defaultdict

class SheetParser(HTMLParser):
    """Parse a single sheet article to extract field values."""
    def __init__(self):
        super().__init__()
        self.in_sheet = False
        self.in_table = False
        self.in_th = False
        self.in_td = False
        self.current_field = None
        self.data = {}
        self.current_text = ""
        self.procurement_ref = None

    def handle_starttag(self, tag, attrs):
        if tag == "article" and any(attr[0] == "class" and "sheet" in attr[1] for attr in attrs):
            self.in_sheet = True
        elif self.in_sheet and tag == "table" and any(attr[0] == "class" and "fields" in attr[1] for attr in attrs):
            self.in_table = True
        elif self.in_table and tag == "th":
            self.in_th = True
            self.current_text = ""
        elif self.in_table and tag == "td":
            self.in_td = True
            self.current_text = ""

    def handle_endtag(self, tag):
        if tag == "article" and self.in_sheet:
            self.in_sheet = False
        elif tag == "table" and self.in_table:
            self.in_table = False
        elif tag == "th" and self.in_th:
            self.in_th = False
            # Clean up field name
            field = self.current_text.strip().lower()
            # Map to our canonical names
            if "procurement reference" in field:
                self.current_field = "procurement_reference"
            elif "invoice grand total" in field:
                self.current_field = "invoice_amount"
            elif "units charged" in field:
                self.current_field = "quantity_invoiced"
            elif "payment deadline" in field:
                self.current_field = "payment_due"
            elif "total order value" in field:
                self.current_field = "order_amount"
            elif "units counted on delivery" in field:
                self.current_field = "quantity_received"
            elif "delivery booked" in field:
                self.current_field = "goods_received"
            elif "funds released" in field:
                self.current_field = "payment_date"
            elif "dock scanner stamp" in field:
                self.current_field = "warehouse_scan_date"
            else:
                self.current_field = None
        elif tag == "td" and self.in_td:
            self.in_td = False
            if self.current_field:
                value = self.current_text.strip()
                # Skip void entries
                if "left blank" in value or value == "":
                    pass
                elif self.current_field == "procurement_reference":
                    # Extract PO number
                    match = re.search(r'PO-\d+', value)
                    if match:
                        self.procurement_ref = match.group()
                        self.data[self.procurement_ref] = {}
                else:
                    # Store value for the current procurement reference
                    if self.procurement_ref:
                        self.data[self.procurement_ref][self.current_field] = value

    def handle_data(self, data):
        if self.in_th or self.in_td:
            self.current_text += data

def parse_html_file(filepath):
    """Parse an HTML file and return a dict mapping PO numbers to field values."""
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    # Split into sheets (each article with class "sheet")
    # We'll parse each sheet separately
    sheets = re.findall(r'<article class="sheet"[^>]*>.*?</article>', content, re.DOTALL)

    result = defaultdict(dict)
    for sheet_html in sheets:
        parser = SheetParser()
        parser.feed(sheet_html)
        for po, fields in parser.data.items():
            for field, value in fields.items():
                result[po][field] = value

    return dict(result)

def normalize_date(date_str):
    """Convert date string like 'Sun., Jan. 11, 2026' to '2026-01-11'."""
    if not date_str:
        return None

    # Remove day of week and any extra punctuation
    date_str = re.sub(r'^[A-Za-z]+\.?,?\s*', '', date_str)

    # Parse month abbreviation
    month_map = {
        'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'Jun': 6,
        'Jul': 7, 'Aug': 8, 'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12
    }

    # Match patterns like "Jan. 11, 2026" or "January 11, 2026"
    match = re.match(r'([A-Za-z]+)\.?\s+(\d{1,2}),?\s+(\d{4})', date_str)
    if match:
        month_str, day, year = match.groups()
        month = month_map.get(month_str[:3])
        if month:
            return f"{int(year):04d}-{month:02d}-{int(day):02d}"

    return None

def normalize_amount(amount_str, unit='USD'):
    """Extract numeric amount from string like 'USD 30,000.00'."""
    if not amount_str:
        return None

    # Remove currency and commas
    match = re.search(r'([\d,]+\.?\d*)', amount_str)
    if match:
        num_str = match.group(1).replace(',', '')
        try:
            # Keep as string with 2 decimal places
            num = float(num_str)
            return f"{num:.2f}"
        except ValueError:
            return None
    return None

def normalize_quantity(qty_str):
    """Extract numeric quantity from string like '286 pcs'."""
    if not qty_str:
        return None

    match = re.search(r'(\d+)', qty_str)
    if match:
        return match.group(1)
    return None

def extract_facts(directory):
    """Extract all facts from the HTML files in the directory."""
    files = {
        'invoices': 'invoices.html',
        'payments': 'payments.html',
        'purchase_orders': 'purchase_orders.html',
        'receipts': 'receipts.html',
        'requisitions': 'requisitions.html',
        'warehouse_scans': 'warehouse_scans.html'
    }

    all_data = {}

    for doc_name, filename in files.items():
        filepath = os.path.join(directory, filename)
        if not os.path.exists(filepath):
            continue

        raw_data = parse_html_file(filepath)
        processed_data = {}

        for po, fields in raw_data.items():
            processed_fields = {}
            for field, value in fields.items():
                if field == 'procurement_reference':
                    processed_fields[field] = value
                elif 'amount' in field or 'value' in field:
                    processed_fields[field] = normalize_amount(value)
                elif 'date' in field or 'due' in field or 'received' in field or 'released' in field:
                    processed_fields[field] = normalize_date(value)
                elif 'quantity' in field:
                    processed_fields[field] = normalize_quantity(value)
                else:
                    processed_fields[field] = value

            processed_data[po] = processed_fields

        all_data[doc_name] = processed_data

    return all_data

def resolve_fact(pair_id, fact_name, facts_data):
    """Resolve a fact for a given pair according to decision rules."""
    po = pair_id.split('::')[-1]

    # Map fact names to document fields
    fact_to_doc_field = {
        'invoice amount': ('invoices', 'invoice_amount'),
        'order amount': ('purchase_orders', 'order_amount'),
        'quantity received': ('receipts', 'quantity_received'),
        'quantity invoiced': ('invoices', 'quantity_invoiced'),
        'goods received': ('receipts', 'goods_received'),
        'payment date': ('payments', 'payment_date'),
        'payment due': ('invoices', 'payment_due')
    }

    if fact_name not in fact_to_doc_field:
        return "ABSENT"

    doc_name, field_name = fact_to_doc_field[fact_name]

    # Special handling for goods_received with fallback
    if fact_name == 'goods received':
        # First try receipts
        if po in facts_data['receipts'] and field_name in facts_data['receipts'][po]:
            value = facts_data['receipts'][po][field_name]
            if value:
                return [value, 'receipts']

        # Fallback to warehouse_scans
        if po in facts_data['warehouse_scans'] and 'warehouse_scan_date' in facts_data['warehouse_scans'][po]:
            value = facts_data['warehouse_scans'][po]['warehouse_scan_date']
            if value:
                return [value, 'warehouse_scans']

        return "ABSENT"

    # For other facts, check the primary document
    if doc_name in facts_data and po in facts_data[doc_name] and field_name in facts_data[doc_name][po]:
        value = facts_data[doc_name][po][field_name]
        if value is not None:
            # Check for conflicts (multiple values in same document)
            # In our parsing, we already aggregated by PO, so if there are multiple sheets
            # with the same PO, we need to check for conflicts
            if doc_name == 'invoices' and po in facts_data['invoices']:
                # Check if we have multiple invoice entries for this PO
                # We need to look at the raw data to see if there are conflicts
                # For simplicity, we'll assume our parser already handled conflicts
                # by taking the first value (which it does)
                pass

            return [value, doc_name]

    return "ABSENT"

def main():
