import json
import os
import re
import sys
from pathlib import Path
from html.parser import HTMLParser
from collections import defaultdict
from datetime import datetime

class SheetParser(HTMLParser):
    """Parse a single sheet/article from the HTML files."""
    def __init__(self):
        super().__init__()
        self.in_sheet = False
        self.in_table = False
        self.in_th = False
        self.in_td = False
        self.current_field = None
        self.data = {}
        self.current_po = None
        self.current_value = []
        self.skip_next = False  # for void fields

    def handle_starttag(self, tag, attrs):
        if tag == 'article' and ('class', 'sheet') in attrs:
            self.in_sheet = True
        elif self.in_sheet and tag == 'table' and ('class', 'fields') in attrs:
            self.in_table = True
        elif self.in_table and tag == 'th':
            self.in_th = True
        elif self.in_table and tag == 'td':
            self.in_td = True
            attrs_dict = dict(attrs)
            if attrs_dict.get('class') == 'void':
                self.skip_next = True
        elif tag == 'strong' and self.in_td:
            # Procurement reference is inside <strong>
            pass

    def handle_endtag(self, tag):
        if tag == 'article' and self.in_sheet:
            self.in_sheet = False
        elif tag == 'table' and self.in_table:
            self.in_table = False
        elif tag == 'th' and self.in_th:
            self.in_th = False
        elif tag == 'td' and self.in_td:
            if self.current_field and self.current_value and not self.skip_next:
                value = ' '.join(self.current_value).strip()
                if self.current_field == 'Procurement reference':
                    self.current_po = value
                else:
                    if self.current_po:
                        self.data[self.current_po] = self.data.get(self.current_po, {})
                        self.data[self.current_po][self.current_field] = value
            self.current_field = None
            self.current_value = []
            self.in_td = False
            self.skip_next = False

    def handle_data(self, data):
        if self.in_th and self.in_table:
            self.current_field = data.strip()
        elif self.in_td and self.in_table and not self.skip_next:
            self.current_value.append(data.strip())

def parse_file(file_path):
    """Parse an HTML file and return dict mapping PO -> field -> value."""
    with open(file_path, 'r', encoding='utf-8') as f:
        content = f.read()
    # Split by article tags to process each sheet separately
    articles = re.findall(r'<article class="sheet"[^>]*>.*?</article>', content, re.DOTALL)
    parser = SheetParser()
    for article in articles:
        parser.feed(article)
    return parser.data

def normalize_date(date_str):
    """Convert date strings like 'Sat., March 21, 2026' to '2026-03-21'."""
    if not date_str or 'left blank' in date_str.lower():
        return None
    # Remove day of week and period
    date_str = re.sub(r'^[A-Za-z]+\.?,?\s*', '', date_str)
    # Abbreviated months
    month_map = {
        'Jan.': 'January', 'Feb.': 'February', 'Mar.': 'March', 'Apr.': 'April',
        'May.': 'May', 'Jun.': 'June', 'Jul.': 'July', 'Aug.': 'August',
        'Sep.': 'September', 'Oct.': 'October', 'Nov.': 'November', 'Dec.': 'December'
    }
    for abbr, full in month_map.items():
        date_str = date_str.replace(abbr, full)
    try:
        dt = datetime.strptime(date_str.strip(), '%B %d, %Y')
        return dt.strftime('%Y-%m-%d')
    except ValueError:
        # Try without comma
        try:
            dt = datetime.strptime(date_str.strip(), '%B %d %Y')
            return dt.strftime('%Y-%m-%d')
        except:
            return None

def normalize_amount(amount_str):
    """Extract numeric amount from strings like 'USD 132,000.00'."""
    if not amount_str:
        return None
    # Remove currency and commas
    match = re.search(r'[\d,]+\.?\d*', amount_str.replace(',', ''))
    if match:
        return match.group(0)
    return None

def normalize_quantity(qty_str):
    """Extract numeric quantity from strings like '100 pcs'."""
    if not qty_str:
        return None
    match = re.search(r'^(\d+)', qty_str)
    if match:
        return match.group(1)
    return None

def load_all_data(dir_path):
    """Load and normalize data from all HTML files."""
    files = {
        'invoices': 'invoices.html',
        'payments': 'payments.html',
        'purchase_orders': 'purchase_orders.html',
        'receipts': 'receipts.html',
        'requisitions': 'requisitions.html',
        'warehouse_scans': 'warehouse_scans.html'
    }
    data = {}
    for doc_name, filename in files.items():
        file_path = Path(dir_path) / filename
        if not file_path.exists():
            continue
        raw = parse_file(file_path)
        normalized = {}
        for po, fields in raw.items():
            normalized[po] = {}
            for field, value in fields.items():
                if 'amount' in field.lower() or 'total' in field.lower() or 'ask' in field.lower():
                    normalized[po][field] = normalize_amount(value)
                elif 'date' in field.lower() or 'deadline' in field.lower() or 'released' in field.lower() or 'booked' in field.lower() or 'stamp' in field.lower() or 'arrival' in field.lower():
                    normalized[po][field] = normalize_date(value)
                elif 'units' in field.lower() or 'quantity' in field.lower() or 'counted' in field.lower() or 'charged' in field.lower():
                    normalized[po][field] = normalize_quantity(value)
                else:
                    normalized[po][field] = value
        data[doc_name] = normalized
    return data

def get_fact_value(data, po, fact_name, rule):
    """Get value for a fact according to decision rules."""
    if rule == 'pa.three_way_match':
        if fact_name == 'invoice amount':
            doc = 'invoices'
            field = 'Invoice grand total'
        elif fact_name == 'order amount':
            doc = 'purchase_orders'
            field = 'Total order value'
        elif fact_name == 'quantity received':
