from typing import Dict, List, Optional, Tuple, Union

def parse_sql_file(file_path: Path) -> List[Dict]:
    """Parse SQL INSERT statements from a file and return list of records."""
    records = []
    try:
        content = file_path.read_text(encoding='utf-8')
    except Exception as e:
        print(f"Error reading {file_path}: {e}", file=sys.stderr)
        return records

    # Find all INSERT statements
    insert_pattern = r'INSERT INTO \w+ \([^)]+\) VALUES\s*\(([^)]+)\)'
    # More robust pattern to handle multiple rows in one INSERT
    insert_pattern = r'INSERT INTO \w+ \([^)]+\) VALUES\s*(.+?);'

    # Extract column names from CREATE TABLE
    create_match = re.search(r'CREATE TABLE (\w+) \((.+?)\);', content, re.DOTALL)
    if not create_match:
        return records

    table_name = create_match.group(1)
    column_defs = create_match.group(2)

    # Parse column names (simple approach)
    lines = column_defs.split('\n')
    column_names = []
    for line in lines:
        line = line.strip()
        if line and not line.startswith('--'):
            # Extract column name (first word before space)
            match = re.match(r'(\w+)', line)
            if match:
                column_names.append(match.group(1))

    # Find all INSERT statements
    insert_matches = re.findall(r'INSERT INTO \w+ \([^)]+\) VALUES\s*(.+?)(?:;|$)', content, re.DOTALL | re.IGNORECASE)

    for match in insert_matches:
        values_block = match.strip()
        # Split into individual rows
        rows = re.split(r'\),\s*\(', values_block)

        for row in rows:
            # Clean up parentheses
            row = row.strip()
            if row.startswith('('):
                row = row[1:]
            if row.endswith(')'):
                row = row[:-1]

            # Parse values (simple CSV-like parsing)
            values = []
            current = ''
            in_quotes = False
            for char in row:
                if char == "'" and not in_quotes:
                    in_quotes = True
                elif char == "'" and in_quotes:
                    in_quotes = False
                elif char == ',' and not in_quotes:
                    values.append(current.strip())
                    current = ''
                    continue
                current += char
            if current:
                values.append(current.strip())

            # Convert NULL to None
            values = [None if v.upper() == 'NULL' else v for v in values]

            # Create record dict
            if len(values) == len(column_names):
                record = {}
                for i, col in enumerate(column_names):
                    value = values[i]
                    if value is not None:
                        # Remove quotes from strings
                        if value.startswith("'") and value.endswith("'"):
                            value = value[1:-1]
                        # Convert numeric values
                        try:
                            if '.' in value:
                                value = float(value)
                            else:
                                value = int(value)
                        except (ValueError, TypeError):
                            pass
                    record[col] = value
                records.append(record)

    return records

def epoch_day_to_date(epoch_day: Optional[int]) -> Optional[str]:
    """Convert epoch day to YYYY-MM-DD string."""
    if epoch_day is None:
        return None
    base_date = datetime(1970, 1, 1)
    target_date = base_date + timedelta(days=epoch_day)
    return target_date.strftime('%Y-%m-%d')

def cents_to_usd(cents: Optional[Union[int, float]]) -> Optional[str]:
    """Convert cents to USD decimal string."""
    if cents is None:
        return None
    dollars = float(cents) / 100.0
    # Format without unnecessary trailing zeros
    result = f"{dollars:.2f}"
    # Remove trailing zeros after decimal
    if '.' in result:
        result = result.rstrip('0').rstrip('.')
    return result

def load_all_data(directory: Path) -> Dict[str, List[Dict]]:
    """Load all SQL files from directory."""
    data = {}
    files = {
        'invoices': 'invoices.sql',
        'payments': 'payments.sql',
        'purchase_orders': 'purchase_orders.sql',
        'receipts': 'receipts.sql',
        'requisitions': 'requisitions.sql',
        'warehouse_scans': 'warehouse_scans.sql'
    }

    for key, filename in files.items():
        file_path = directory / filename
        if file_path.exists():
            data[key] = parse_sql_file(file_path)
        else:
            print(f"Warning: {filename} not found in {directory}", file=sys.stderr)
            data[key] = []

    return data

