    for inv in invoices:
        if inv.get('ord_code') == ord_code and inv.get('billed_cents') is not None:
            amounts.append(inv['billed_cents'])

    if not amounts:
        return None, None

    # Check for conflicts
    if len(set(amounts)) > 1:
        return "CONFLICT", None

    return cents_to_usd(amounts[0]), "invoices"

